from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class EthlkParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_connectorLabel(execution_config)
        self.set_modDN()

        if not self.is_mo_ecpri:
            self.set_parameter('administrativeState', "unlocked")
            self.set_parameter('l2IngressRate', "25000000")
            self.set_parameter('speedAndDuplex', self.enb_ent_config.get('enb_eif_speed_and_duplex', "AUTODETECT"))

    def set_connectorLabel(self, execution_config):
        if self.is_mo_ecpri:
            radio_ent = self.enb_ent_config["radios"][self.mo_num]
            self.set_parameter('connectorLabel', f'S-RF{radio_ent["port"]}')
        else:
            enb_eif = "EIF1"
            self.set_parameter('connectorLabel', self.enb_ent_config.get('enb_eif', enb_eif))

    def set_modDN(self):
        if self.is_mo_ecpri:
            tnl_id = self.tnl_id
            radio_ent = self.enb_ent_config["radios"][self.mo_num]
            if 'bbmod' in radio_ent:
                radio_src = f'BBMOD-{tnl_id - 1}'
            else:
                radio_src = f'SMOD-{radio_ent["smod"]}'
            self.set_parameter('modDN', f'MRBTS-{self.enb_ent_config["id"]}/EQM-1/APEQM-1/CABINET-1/{radio_src}')
        else:
            self.set_parameter('modDN', f'MRBTS-{self.enb_ent_config["id"]}/EQM-1/APEQM-1/CABINET-1/SMOD-1')
